'use client'

import { useEffect, useState } from 'react'
import { useParams } from 'next/navigation'
import ClientDashboard from '@/components/dashboard/client-dashboard'
import CodeEditor from '@/components/features/code-editor'
import AIResponseBox from '@/components/features/ai-response-box'
import FlowchartRenderer from '@/components/features/flowchart-renderer'

export default function FeaturePage() {
  const params = useParams()
  const slug = params.slug as string

  const getPageContent = () => {
    switch (slug) {
      case 'documentation':
        return (
          <div className="grid grid-cols-2 gap-6 h-full p-6">
            <CodeEditor />
            <AIResponseBox title="Generated Documentation" />
          </div>
        )
      case 'explain':
        return (
          <div className="grid grid-cols-2 gap-6 h-full p-6">
            <CodeEditor />
            <AIResponseBox title="Code Explanation" />
          </div>
        )
      case 'tests':
        return (
          <div className="grid grid-cols-2 gap-6 h-full p-6">
            <CodeEditor />
            <AIResponseBox title="Generated Unit Tests" />
          </div>
        )
      case 'optimize':
        return (
          <div className="grid grid-cols-2 gap-6 h-full p-6">
            <CodeEditor />
            <AIResponseBox title="Optimization Suggestions" />
          </div>
        )
      case 'flowchart':
        return (
          <div className="grid grid-cols-2 gap-6 h-full p-6">
            <CodeEditor />
            <FlowchartRenderer />
          </div>
        )
      case 'github':
        return (
          <div className="p-6">
            <AIResponseBox title="GitHub Repository Analysis" />
          </div>
        )
      default:
        return <div className="p-6">Select a feature from the sidebar</div>
    }
  }

  return getPageContent()
}
